import {useQuery} from "@tanstack/react-query"
import Form from "../"

function App() {
  const {data} = useQuery({
    queryKey: ["todo"],
    queryFn : async () => await (await fetch("http://localhost:8000/todo")).json()
  });
  console.log(data);
  return (
    <div className="App">

      <h1> React Query </h1>
      <Form />
    </div>
  );
}

export default App;
